    # used[i] == 1 once physical row i has been selected as a pivot. Rows are
    # never physically swapped; the permutation is tracked only through 'used'
    # and its parity is accumulated via the inversion formula.
    used = tl.zeros([BLOCK_N], dtype=tl.int32)
    swap_count = 0
    neg_count = 0
    zero_count = 0
    nan_count = 0
    log_sum = 0.0

    for k in range(n):
        # Column k (full-tile reduction).
        col_k = tl.sum(tl.where(cols[None, :] == k, work, 0.0), axis=1)

        # Pivot search over rows not yet eliminated.
        abs_col = tl.where((used != 0) | (rows >= n), -1.0, tl.abs(col_k))
        pivot_val = tl.max(abs_col, axis=0)
        pivot_row = tl.min(tl.where(abs_col == pivot_val, rows, BLOCK_N), axis=0)

        # Permutation parity: sign(perm) = (-1)^(sum_k #unused j < p_k).
        inv_inc = tl.sum(tl.where((rows < pivot_row) & (used == 0) & (rows < n), 1, 0))
        swap_count += inv_inc

        # Pivot value == final U[k,k] (row p is never updated later).
        pivot = tl.sum(tl.where(rows == pivot_row, col_k, 0.0), axis=0)
        safe_pivot = tl.where(pivot == 0.0, 1.0, pivot)

        neg_count += tl.where(pivot < 0.0, 1, 0)
        zero_count += tl.where(pivot == 0.0, 1, 0)
        nan_count += tl.where(pivot != pivot, 1, 0)
        log_sum += tl.log(tl.abs(pivot))

        # Multipliers for active rows (excludes pivot row and used rows;
        # zeroed on an exact-zero pivot, mirroring LAPACK's skip).
        m = tl.where(
            (rows != pivot_row) & (used == 0) & (rows < n) & (pivot != 0.0),
            col_k / safe_pivot,
            0.0,
        )

        # U row == pivot row (full-tile reduction).
        u_row = tl.sum(tl.where(rows[:, None] == pivot_row, work, 0.0), axis=0)

        # Rank-1 trailing update (used rows have m == 0, so only active rows
        # change; padded columns are masked out).
        upd_mask = (cols[None, :] > k) & (cols[None, :] < n)
        work = tl.where(upd_mask, work - m[:, None] * u_row[None, :], work)

        used = tl.where(rows == pivot_row, 1, used)

    parity = (neg_count + swap_count) % 2
    sign_val = tl.where(parity == 0, 1.0, -1.0)
    sign_val = tl.where((zero_count > 0) | (nan_count > 0), 0.0, sign_val)

    tl.store(sign_out + pid, sign_val.to(sign_out.dtype.element_ty))
