def linalg_slogdet(A):
    if A.dim() < 2:
        raise RuntimeError(
            "linalg_slogdet: input tensor must have at least 2 dimensions"
        )
    n = A.shape[-1]
    if A.shape[-2] != n:
        raise RuntimeError(
            "linalg_slogdet: input tensor must be a batch of square matrices"
        )
    if A.dtype != torch.float32:
        raise RuntimeError("linalg_slogdet: expected input of floating type float32")

    A_c = A.contiguous()

    batch_size = 1
    for d in A.shape[:-2]:
        batch_size *= d

    sign = torch.empty(A.shape[:-2], dtype=torch.float32, device=A.device)
    logabsdet = torch.empty(A.shape[:-2], dtype=torch.float32, device=A.device)

    if batch_size == 0:
        return torch.return_types.linalg_slogdet((sign, logabsdet))

